        }
    }

    int idx = 0;
    while (front < rear) {
        int u = queue[front++];
        result[idx++] = u;

        Node* temp = adj[u];
        while (temp != NULL) {
            int v = temp->vertex;
            indegree[v]--;
            if (indegree[v] == 0) {
                queue[rear++] = v;
            }
            temp = temp->next;
        }
