typedef struct Node {
    int to;
    struct Node *next;
} Node;

int main(void) {
    int V, E;
    if (scanf("%d %d", &V, &E) != 2) return 0;

    Node **adj = (Node **)calloc(V, sizeof(Node *));
    int *indegree = (int *)calloc(V, sizeof(int));
    int *queue = (int *)malloc(V * sizeof(int));
    int *result = (int *)malloc(V * sizeof(int));

    for (int i = 0; i < E; i++) {
        int u, v;
        scanf("%d %d", &u, &v);

        Node *node = (Node *)malloc(sizeof(Node));
        node->to = v;
        node->next = adj[u];
        adj[u] = node;

        indegree[v]++;
    }

    int front = 0, back = 0;
    for (int i = 0; i < V; i++) {
        if (indegree[i] == 0) {
            queue[back++] = i;
        }
    }

    int count = 0;
    while (front < back) {
        int u = queue[front++];
        result[count++] = u;

        for (Node *cur = adj[u]; cur != NULL; cur = cur->next) {
            int v = cur->to;
            indegree[v]--;
            if (indegree[v] == 0) {
                queue[back++] = v;
            }
        }
    }

    for (int i = 0; i < count; i++) {
        if (i) printf(" ");
        printf("%d", result[i]);
    }
    printf("\n");

    for (int i = 0; i < V; i++) {
        Node *cur = adj[i];
        while (cur) {
            Node *tmp = cur;
            cur = cur->next;
            free(tmp);
        }
    }

    free(adj);
    free(indegree);
    free(queue);
    free(result);

    return 0;
}

